(()=>{
 const $=id=>document.getElementById(id),repo='https://github.com/the-mayankjha/morphlet',api='https://api.github.com/repos/the-mayankjha/morphlet/releases?per_page=12';let releases=[],platform='mac';try{platform=sessionStorage.getItem('morphlet.download.platform')||'mac';}catch{}if(!['mac','windows','linux'].includes(platform))platform='mac';
 const labels={mac:'macOS',windows:'Windows',linux:'Linux'};
 function syncPlatformUI(){
  document.querySelectorAll('[data-mac-only]').forEach(el=>el.hidden=platform!=='mac');
  document.querySelectorAll('[data-download-os]').forEach(el=>el.hidden=el.dataset.downloadOs!==platform);
  document.querySelectorAll('[data-os]').forEach(button=>{
   button.setAttribute('aria-pressed',String(button.dataset.os===platform));
   if(!button.querySelector('.platform-logo'))button.prepend(icon(button.dataset.os));
   button.onclick=()=>{platform=button.dataset.os;try{sessionStorage.setItem('morphlet.download.platform',platform);}catch{}syncPlatformUI();if($('release-overview')&&releases.length)renderPlatform(selected());};
  });
 }

 const node=(tag,text,className)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el;};
 function icon(os){const image=document.createElement('img');image.src='assets/platforms/'+os+'.svg';image.alt='';image.className='platform-logo platform-'+os;image.setAttribute('aria-hidden','true');return image;}
 function link(text,href,className){const el=node('a',text,className);el.href=href;return el;}
 const date=value=>new Intl.DateTimeFormat('en',{day:'numeric',month:'long',year:'numeric'}).format(new Date(value));
 const megabytes=asset=>(asset.size/1e6).toFixed(1)+' MB';
 const validAsset=asset=>{try{const url=new URL(asset.browser_download_url);return url.origin==='https://github.com'&&url.pathname.startsWith('/the-mayankjha/morphlet/releases/download/')&&typeof asset.name==='string'&&Number.isFinite(asset.size);}catch{return false;}};
 function clean(data){return Array.isArray(data)?data.filter(r=>!r.draft&&typeof r.tag_name==='string'&&typeof r.body==='string'&&Array.isArray(r.assets)&&!isNaN(Date.parse(r.published_at))).map(r=>({tag_name:r.tag_name,name:r.name,body:r.body,html_url:r.html_url,published_at:r.published_at,prerelease:!!r.prerelease,assets:r.assets.filter(validAsset).map(a=>({name:a.name,browser_download_url:a.browser_download_url,size:a.size}))})):[];}
 const installers=(release,os)=>release.assets.filter(a=>os==='mac'?/-mac-(arm64|x64)\.dmg$/i.test(a.name):os==='windows'?/-windows-x64-setup\.exe$/i.test(a.name):/\.(AppImage|deb)$/i.test(a.name));
 const assetLabel=asset=>/mac-arm64/.test(asset.name)?'Apple Silicon · DMG':/mac-x64/.test(asset.name)?'Intel · DMG':/\.exe$/i.test(asset.name)?'Windows x64 · Installer':/\.AppImage$/i.test(asset.name)?'Linux x64 · AppImage':'Linux x64 · Debian';
 function summary(release){const lines=release.body.split('\n').map(l=>l.trim()).filter(l=>l&&!l.startsWith('#'));return (lines[0]||'See the release notes for the changes in this version.').replace(/^[-*]\s*/,'').replace(/\*\*|`/g,'').slice(0,280);}
 function inline(el,text){for(const part of text.split(/(\*\*[^*]+\*\*|`[^`]+`)/g)){if(part.startsWith('**')&&part.endsWith('**'))el.append(node('strong',part.slice(2,-2)));else if(part.startsWith('`')&&part.endsWith('`'))el.append(node('code',part.slice(1,-1)));else el.append(document.createTextNode(part));}return el;}
 function notes(text){const box=node('div',undefined,'notes-body');let list=null,code=null;for(const raw of text.split('\n')){const line=raw.trim();if(line.startsWith('```')){if(code){box.append(code);code=null;}else code=node('pre');list=null;continue;}if(code){code.textContent+=(code.textContent?'\n':'')+raw;continue;}if(!line){list=null;continue;}const heading=line.match(/^(#{1,6})\s+(.+)/);if(heading){box.append(inline(node('h'+Math.min(4,heading[1].length+1)),heading[2]));list=null;}else if(/^[-*]\s/.test(line)){if(!list){list=node('ul');box.append(list);}list.append(inline(node('li'),line.replace(/^[-*]\s+/,'')));}else if(/^---+$/.test(line)){list=null;}else{box.append(inline(node('p'),line));list=null;}}if(code)box.append(code);return box;}
 function selected(){const requested=new URLSearchParams(location.search).get('version');return releases.find(r=>r.tag_name===requested)||releases[0];}
 function installerCard(release,os){const card=node('article',undefined,'installer-card');card.dataset.downloadOs=os;card.append(icon(os),node('p','MORPHLET FOR '+labels[os].toUpperCase(),'eyebrow'),node('h2',labels[os]),node('p',os==='mac'?'Choose the architecture that matches your Mac.':os==='windows'?'A native x64 installer for your Windows desktop.':'Choose an AppImage or Debian package for x64.'));const assets=installers(release,os);if(!assets.length){card.append(link('View available packages',release.html_url||repo+'/releases','subtle-link'));return card;}const label=node('label',os==='mac'?'Mac architecture':os==='linux'?'Package type':'Installer'),select=node('select');select.id='package-'+os;label.htmlFor=select.id;assets.forEach(a=>{const option=node('option',assetLabel(a));option.value=a.name;select.append(option);});card.append(label,select);const primary=link('Download '+labels[os],assets[0].browser_download_url,'button dark-button'),meta=node('span',undefined,'asset-meta'),alternatives=node('div',undefined,'asset-alternatives');card.append(primary,meta,alternatives);const update=()=>{const asset=assets.find(a=>a.name===select.value)||assets[0];primary.href=asset.browser_download_url;primary.textContent='Download '+(/\.dmg$/.test(asset.name)?'DMG':/\.exe$/.test(asset.name)?'installer':/\.deb$/.test(asset.name)?'DEB':'AppImage')+' ＋';meta.textContent=megabytes(asset)+' · '+asset.name;alternatives.replaceChildren();const checksum=release.assets.find(a=>a.name===asset.name+'.sha256');if(checksum)alternatives.append(link('SHA-256 checksum',checksum.browser_download_url));if(os==='mac'){const zip=release.assets.find(a=>a.name===asset.name.replace(/\.dmg$/,'.zip'));if(zip)alternatives.append(link('ZIP archive',zip.browser_download_url));}alternatives.append(link('Release notes','releases.html?version='+encodeURIComponent(release.tag_name)+'#release-notes'));};select.onchange=update;update();return card;}
 function renderDownload(){if(!$('installer-cards'))return;const release=releases[0];$('download-version').textContent=release.tag_name+' · '+(release.prerelease?'Prerelease':'Stable')+' · '+date(release.published_at);$('installer-cards').replaceChildren(...['mac','windows','linux'].map(os=>installerCard(release,os)));syncPlatformUI();}
 const instructions={mac:[['Choose your Mac','Use Apple Silicon for M-series Macs, or Intel for an Intel Mac.'],['Open the DMG','Find the downloaded disk image and double-click to open it.'],['Move to Applications','Drag Morphlet into Applications, then eject the disk image.'],['First launch & Studio','If Apple cannot verify the app, follow the Mac first-launch guide below. Once opened, use the menu-bar icon to open Studio.']],windows:[['Get the installer','Download the x64 setup executable from the installer card.'],['Run setup','Open the downloaded file and follow the installer prompts.'],['Launch Morphlet','Open Morphlet from the Start menu or installed shortcut.'],['Find your tray icon','Use the notification area to open Studio. The icon may be in overflow.']],linux:[['Choose a package','Use AppImage for a portable application, or DEB for Debian-based systems.'],['Prepare the package','Mark the AppImage executable, or install the DEB with your package manager.'],['Launch Morphlet','Run the AppImage or open the installed application. FUSE may be needed for AppImage.'],['Open your workspace','Use Studio or the tray menu. Tray support depends on your desktop.']]};
 function renderPlatform(release){syncPlatformUI();const card=node('div',undefined,'release-install-card'),assets=installers(release,platform);card.append(icon(platform),node('p','MORPHLET FOR '+labels[platform].toUpperCase(),'eyebrow'),node('h3',platform==='mac'?'Choose your Mac installer.':platform==='windows'?'Your Windows installer.':'Choose your Linux package.'),node('p',platform==='mac'?'Choose the architecture that matches your Mac. Both installers include the full Morphlet experience.':platform==='windows'?'The x64 setup installer for Windows.':'AppImage and Debian packages for Linux x64.'));for(const asset of assets){const a=link('',asset.browser_download_url,'release-download'),detail=node('div');detail.append(node('strong',assetLabel(asset)),node('small',megabytes(asset)+' · download size'));a.append(node('span',/\.dmg$/i.test(asset.name)?'DMG':/\.exe$/i.test(asset.name)?'EXE':/\.deb$/i.test(asset.name)?'DEB':'APP','package-symbol'),detail,node('span','＋'));card.append(a);}if(!assets.length)card.append(node('p','No installer is available for this platform in this release.'));card.append(node('p',platform==='mac'?'macOS packages are not notarized. See the Mac first-launch guide below.':'Unsigned build. Download only from the official repository.','asset-meta'));card.append(link('Read the release notes','#release-notes','subtle-link'));if(platform==='mac')card.append(link('Mac installation & first-launch guide','#mac-install','subtle-link'));$('release-installer').replaceChildren(card);$('install-platform-label').textContent='INSTALLATION / '+labels[platform].toUpperCase();$('install-guide').replaceChildren(...instructions[platform].map(([title,copy],i)=>{const el=node('article',undefined,'install-step');el.append(node('span',String(i+1).padStart(2,'0')),node('h3',title),node('p',copy));return el;}));}
 function renderRelease(){if(!$('release-overview'))return;const release=selected(),overview=$('release-overview');overview.replaceChildren(node('p',release===releases[0]?'LATEST RELEASE':'PREVIOUS RELEASE','eyebrow'),node('h2','Morphlet '+release.tag_name.replace(/^v/,''),'release-name'),node('h3',release.name||release.tag_name,'release-subtitle'),node('p',summary(release),'release-summary'));const facts=node('dl',undefined,'release-facts');for(const [name,value]of [['RELEASED',date(release.published_at)],['CHANNEL',release.prerelease?'Prerelease':'Stable'],['PLATFORMS','macOS · Windows · Linux']]){const div=node('div');div.append(node('dt',name),node('dd',value));facts.append(div);}overview.append(facts);renderPlatform(release);$('latest-notes').replaceChildren(notes(release.body));const history=$('release-history');history.replaceChildren();const years=[...new Set(releases.map(r=>new Date(r.published_at).getFullYear()))];for(const year of years){const group=node('div',undefined,'history-year'),entries=node('div',undefined,'history-entries');group.append(node('span',String(year)),entries);for(const r of releases.filter(v=>new Date(v.published_at).getFullYear()===year)){const details=node('details',undefined,'history-entry');details.open=r.tag_name===release.tag_name;const title=node('summary'),middle=node('div');middle.append(node('b',r.name||'Morphlet '+r.tag_name),node('small',date(r.published_at)+' · '+(r.prerelease?'Prerelease':'Stable')));title.append(node('span',r.tag_name.replace(/^v/,'')),middle,node('i','＋'));const content=node('div',undefined,'history-content');content.append(node('p',summary(r)));const platforms=node('div',undefined,'history-platforms');for(const os of ['mac','windows','linux']){const asset=installers(r,os)[0];if(asset)platforms.append(link(labels[os]+' · '+(/arm64/.test(asset.name)?'Apple Silicon':/\.deb$/.test(asset.name)?'DEB':/\.AppImage$/.test(asset.name)?'AppImage':'x64'),asset.browser_download_url));}content.append(platforms);const links=node('div',undefined,'history-links');links.append(link('View release & all installers','releases.html?version='+encodeURIComponent(r.tag_name)+'#latest-release'),link('View on GitHub',r.html_url||repo+'/releases'));content.append(links,notes(r.body));const all=node('details',undefined,'all-assets');all.append(node('summary','All '+r.assets.length+' files, archives & checksums'));const list=node('ul');for(const asset of r.assets){const li=node('li');li.append(link(asset.name,asset.browser_download_url),document.createTextNode(' · '+megabytes(asset)));list.append(li);}all.append(list);content.append(all);details.append(title,content);entries.append(details);}history.append(group);}}
 function render(data){const value=clean(data);if(!value.length)throw Error('No published releases');if(JSON.stringify(releases)===JSON.stringify(value))return;releases=value;renderDownload();renderRelease();}
 async function load(){let loaded=false;try{const response=await fetch('assets/releases.json');if(!response.ok)throw Error();render(await response.json());loaded=true;}catch{}try{const response=await fetch(api,{signal:AbortSignal.timeout(6000),headers:{Accept:'application/vnd.github+json'}});if(!response.ok)throw Error();render(await response.json());if($('release-source'))$('release-source').textContent='Latest published release information from GitHub.';}catch{if(!loaded){const target=$('installer-cards')||$('release-overview');target.replaceChildren(node('p','Release information is temporarily unavailable.','download-error'),link('Open GitHub Releases',repo+'/releases','subtle-link'));}if($('release-source'))$('release-source').textContent=loaded?'Showing verified release information. Live refresh is temporarily unavailable.':'View official releases on GitHub for downloads.';}}
 syncPlatformUI();
 load();
})();
